import{_ as m,a0 as l,w as p,s as n,ao as i,I as a,x as e,a1 as r,A as s}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const b=JSON.parse('{"title":"Mattermost 7.0 发布，扩展了工作流平台 | LCTT x X-CMD","titleTemplate":false,"description":"Mattermost 7.0 发布，扩展了工作流平台 | LCTT (202206) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Mattermost 7.0 发布，扩展了工作流平台 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Mattermost 7.0 发布，扩展了工作流平台 | LCTT (202206) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202206/20220616 Mattermost Extends workflow platform with 7.0 release","title":"Mattermost 7.0 发布，扩展了工作流平台","tag":"202206","desc":""},"relativePath":"202206/20220616 Mattermost Extends workflow platform with 7.0 release.md","filePath":"[post].md"}'),f={name:"202206/20220616 Mattermost Extends workflow platform with 7.0 release.md"};function d(u,t,w,T,M,x){const o=l("Link");return p(),n("div",null,[t[15]||(t[15]=i('<h1 id="mattermost-7-0-发布-扩展了工作流平台" tabindex="-1">Mattermost 7.0 发布，扩展了工作流平台 <a class="header-anchor" href="#mattermost-7-0-发布-扩展了工作流平台" aria-label="Permalink to “Mattermost 7.0 发布，扩展了工作流平台”">​</a></h1><p><img src="https://www.opensourceforu.com/wp-content/uploads/2022/06/marttermost-e1655377462300.jpeg" alt="Mattermost"></p><p>自 2016 年开源以来，Mattermost 一直在开发一个具有不断增加的用例的消息传递平台。6 月 16 日，Mattermost 7.0 平台发布，其中包括了新的语音呼叫、工作流模板和用于开源技术的应用框架。新版本扩展了 2021 年 10 月发布的 6.0 版本引入的功能。一直以来，Mattermost 都在与包括 Slack、Atlassian 和 Asana 在内的几家大公司，竞争不断增长的协作工具市场。另一方面，Mattermost 侧重于对开发者的支持，尽管该平台也可用于安全和 IT 运营。</p><p>Mattermost 的软件同时提供有商业版和开源版，目前它们都升级到了 7.0 版。Tien 解释说，Mattermost 的商业平台是建立在开源基础上的。在开放核心模型中，开源版作为软件的基础或核心，专有的企业功能则内置于商业版中。合规性、规模性和高级配置是 Mattermost 的关键企业功能。Tien 声称，开源版本对于中小型团队来说已经足够了。他认为，拥有 500 名或更多用户的团队才需要考虑使用商业版。</p><p>Tien 认为开源也关乎社区贡献。Mattermost 开源项目有超过 4000 名个人贡献者，他们贡献了超过 30000 行代码。</p><p>以前，Mattermost 依赖集成第三方呼叫服务（例如 Zoom）来启用语音呼叫功能。在 7.0 版本中，它通过开源 WebRTC 协议引入了呼叫功能的直接集成，所有现代 Web 浏览器都支持该协议。直接集成呼叫功能的目标是为协作提供单一平台，这符合 Tien 对该平台的总体愿景。现在，除了提供集成工具以实现协作之外，该平台还会增加“工作流模板”功能，以帮助（用户）组织构建可重复的流程。</p><p>工作流概念采用了 <ruby>剧本<rt>playbook</rt></ruby>，其中包含了为“特定类型的操作”所执行的动作和操作的清单。例如，在发生服务故障或网络安全事件时，公司可以为事件响应创建工作流模板。</p><p>这个清单可以链接到 Mattermost <ruby>操作<rt>operation</rt></ruby>，例如让特定用户发起呼叫，并协助生成报告。Tien 表示，Mattermost 还与常见的开发者工具集成，并且工作流模板的功能将随着时间的推移而扩展，以便使用第三方工具来实现更多自动化。</p><hr>',9)),a("p",null,[t[1]||(t[1]=e("via: ",-1)),r(o,{href:"https://www.opensourceforu.com/2022/06/mattermost-extends-workflow-platform-with-7-0-release/"},{default:s(()=>[...t[0]||(t[0]=[e("https://www.opensourceforu.com/2022/06/mattermost-extends-workflow-platform-with-7-0-release/",-1)])]),_:1})]),a("p",null,[t[6]||(t[6]=e("作者：",-1)),r(o,{href:"https://www.opensourceforu.com/author/laveesh-kocher/"},{default:s(()=>[...t[2]||(t[2]=[e("Laveesh Kocher",-1)])]),_:1}),t[7]||(t[7]=e(" 选题：",-1)),r(o,{href:"https://github.com/lkxed"},{default:s(()=>[...t[3]||(t[3]=[e("lkxed",-1)])]),_:1}),t[8]||(t[8]=e(" 译者：",-1)),r(o,{href:"https://github.com/lkxed"},{default:s(()=>[...t[4]||(t[4]=[e("lkxed",-1)])]),_:1}),t[9]||(t[9]=e(" 校对：",-1)),r(o,{href:"https://github.com/wxy"},{default:s(()=>[...t[5]||(t[5]=[e("wxy",-1)])]),_:1})]),a("p",null,[t[12]||(t[12]=e("本文由 ",-1)),r(o,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...t[10]||(t[10]=[e("LCTT",-1)])]),_:1}),t[13]||(t[13]=e(" 原创编译，",-1)),r(o,{href:"https://linux.cn/"},{default:s(()=>[...t[11]||(t[11]=[e("Linux中国",-1)])]),_:1}),t[14]||(t[14]=e(" 荣誉推出",-1))])])}const g=m(f,[["render",d]]);export{b as __pageData,g as default};
